import { Component, inject, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { HttpClient } from '@angular/common/http';
import { firstValueFrom } from 'rxjs';
import { errorText } from '../util';

type Pricing = { inputPerMillion: number | null; outputPerMillion: number | null; currency: string };
type Usage = { input_tokens: number; output_tokens: number };

@Component({
  selector: 'app-tokens',
  imports: [FormsModule],
  template: `
    <h1>Tokens and cost</h1>
    <p class="hint">Count tokens before you send, then see what a real request used and what it cost.</p>

    <div class="card">
      <label for="t">Text</label>
      <textarea id="t" [(ngModel)]="text" placeholder="Paste a job description or a resume here..."></textarea>
      <button class="secondary" (click)="count()" [disabled]="busy() || !text.trim()">Count input tokens</button>
      <button (click)="send()" [disabled]="busy() || !text.trim()">Send to Claude</button>
      @if (error()) { <div class="err">{{ error() }}</div> }
      @if (counted() !== null) { <p>This text is about <strong>{{ counted() }}</strong> input tokens.</p> }
    </div>

    @if (calls().length) {
      <div class="card">
        <h2>Usage log</h2>
        <table>
          <thead><tr><th>#</th><th>Input</th><th>Output</th><th>Cost</th></tr></thead>
          <tbody>
            @for (c of calls(); track $index) {
              <tr><td>{{ $index + 1 }}</td><td>{{ c.input_tokens }}</td><td>{{ c.output_tokens }}</td><td>{{ cost(c) }}</td></tr>
            }
          </tbody>
        </table>
        <p><strong>Total this session: {{ totalCost() }}</strong></p>
        @if (!hasPrices()) {
          <p class="muted">Add PRICE_INPUT_PER_MTOK and PRICE_OUTPUT_PER_MTOK to your .env file to see money amounts.</p>
        }
      </div>
    }
  `,
})
export class TokensPage {
  private http = inject(HttpClient);

  text = '';
  busy = signal(false);
  error = signal('');
  counted = signal<number | null>(null);
  calls = signal<Usage[]>([]);
  pricing = signal<Pricing>({ inputPerMillion: null, outputPerMillion: null, currency: 'USD' });

  constructor() {
    firstValueFrom(this.http.get<Pricing>('/api/pricing')).then((p) => this.pricing.set(p)).catch(() => {});
  }

  hasPrices() {
    const p = this.pricing();
    return p.inputPerMillion !== null && p.outputPerMillion !== null;
  }

  cost(u: Usage): string {
    const p = this.pricing();
    if (!this.hasPrices()) return '-';
    const money = (u.input_tokens / 1_000_000) * p.inputPerMillion! + (u.output_tokens / 1_000_000) * p.outputPerMillion!;
    return `${money.toFixed(6)} ${p.currency}`;
  }

  totalCost(): string {
    const p = this.pricing();
    if (!this.hasPrices()) return '-';
    const money = this.calls().reduce(
      (sum, u) => sum + (u.input_tokens / 1_000_000) * p.inputPerMillion! + (u.output_tokens / 1_000_000) * p.outputPerMillion!,
      0,
    );
    return `${money.toFixed(6)} ${p.currency}`;
  }

  async count() {
    await this.run(async () => {
      const r = await firstValueFrom(this.http.post<{ inputTokens: number }>('/api/count', { text: this.text }));
      this.counted.set(r.inputTokens);
    });
  }

  async send() {
    await this.run(async () => {
      const r = await firstValueFrom(this.http.post<{ usage: Usage }>('/api/ask', { question: this.text }));
      this.calls.update((list) => [...list, r.usage]);
    });
  }

  private async run(job: () => Promise<void>) {
    this.busy.set(true);
    this.error.set('');
    try { await job(); } catch (e) { this.error.set(errorText(e)); } finally { this.busy.set(false); }
  }
}

const reply = await client.messages.create({
  model: MODEL,
  max_tokens: 600,
  system: 'You are a careful career coach. Keep answers short and never invent facts about the user.',
  messages: [
    { role: 'user', content: 'I drove a forklift for 4 years. How do I write that on my CV?' },
  ],
});

// after Claude answered:
history.push({ role: 'assistant', content: reply.text });
// the user asks a follow-up:
history.push({ role: 'user', content: 'Make it shorter.' });
// send the WHOLE history again:
await client.messages.create({ model: MODEL, max_tokens: 600, system, messages: history });

// Clean the chat history that comes from the browser. Never trust it.
//  - only "user" and "assistant" roles
//  - text only, limited length
//  - keep the last 20 messages
//  - the first message must be from the user, and the last one too
export function cleanMessages(input) {
  if (!Array.isArray(input)) return [];
  let list = input
    .filter((m) => m && (m.role === 'user' || m.role === 'assistant') && typeof m.content === 'string' && m.content.trim())
    .map((m) => ({ role: m.role, content: m.content.slice(0, 4000) }))
    .slice(-20);
  while (list.length && list[0].role !== 'user') list.shift();
  return list;
}

export const lastIsUser = (list) => list.length > 0 && list[list.length - 1].role === 'user';

import { Router } from 'express';
import { client, MODEL, textOf } from '../claude.js';
import { cleanMessages, lastIsUser } from '../messages.js';

const router = Router();

// POST /api/chat  { system?, messages: [{role, content}] }
// Claude has no memory, so the browser sends the whole conversation every time.
router.post('/chat', async (req, res) => {
  const system = String(req.body?.system || '').slice(0, 2000);
  const messages = cleanMessages(req.body?.messages);
  if (!lastIsUser(messages)) {
    return res.status(400).json({ error: { message: 'Send at least one message from the user.' } });
  }

  const reply = await client.messages.create({
    model: MODEL,
    max_tokens: 600,
    ...(system ? { system } : {}),
    messages,
  });

  res.json({ text: textOf(reply), usage: reply.usage, stopReason: reply.stop_reason });
});

export default router;

import { Component, inject, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { HttpClient } from '@angular/common/http';
import { firstValueFrom } from 'rxjs';
import { errorText } from '../util';

type Msg = { role: 'user' | 'assistant'; content: string };
type ChatReply = { text: string; usage: { input_tokens: number; output_tokens: number }; stopReason: string };

@Component({
  selector: 'app-chat',
  imports: [FormsModule],
  template: `
    <h1>Chat with memory</h1>
    <p class="hint">Claude does not remember earlier calls. This page keeps the history and sends it every time.</p>

    <div class="card">
      <label for="sys">System prompt (rules and persona)</label>
      <textarea id="sys" [(ngModel)]="system" style="min-height:70px"></textarea>

      <label for="keep">Messages to send each time</label>
      <select id="keep" [(ngModel)]="keep">
        <option [ngValue]="4">Last 4</option>
        <option [ngValue]="10">Last 10</option>
        <option [ngValue]="20">Last 20</option>
      </select>
    </div>

    <div class="card">
      @for (m of history(); track $index) {
        <p><strong>{{ m.role === 'user' ? 'You' : 'Claude' }}:</strong> <span class="answer">{{ m.content }}</span></p>
      } @empty {
        <p class="muted">No messages yet. Say hello.</p>
      }
      @if (cutOff()) { <div class="err">The reply was cut off because it hit the length limit. Ask Claude to continue.</div> }
      @if (error()) { <div class="err">{{ error() }}</div> }

      <label for="msg">Your message</label>
      <textarea id="msg" [(ngModel)]="draft" style="min-height:70px"></textarea>
      <button (click)="send()" [disabled]="busy() || !draft.trim()">{{ busy() ? 'Thinking...' : 'Send' }}</button>
      <button class="secondary" (click)="clear()">Clear chat</button>
      <p class="muted">Sending {{ toSend().length }} of {{ history().length }} messages.</p>
    </div>
  `,
})
export class ChatPage {
  private http = inject(HttpClient);

  system = 'You are a careful career coach. Keep answers short and never invent facts about the user.';
  keep = 10;
  draft = '';
  history = signal<Msg[]>([]);
  busy = signal(false);
  error = signal('');
  cutOff = signal(false);

  toSend() {
    return this.history().slice(-this.keep);
  }

  async send() {
    const text = this.draft.trim();
    if (!text) return;
    this.history.update((h) => [...h, { role: 'user', content: text }]);
    this.draft = '';
    this.busy.set(true);
    this.error.set('');
    this.cutOff.set(false);
    try {
      const r = await firstValueFrom(
        this.http.post<ChatReply>('/api/chat', { system: this.system, messages: this.toSend() }),
      );
      this.history.update((h) => [...h, { role: 'assistant', content: r.text }]);
      this.cutOff.set(r.stopReason === 'max_tokens');
    } catch (e) {
      this.error.set(errorText(e));
    } finally {
      this.busy.set(false);
    }
  }

  clear() {
    this.history.set([]);
    this.error.set('');
    this.cutOff.set(false);
  }
}

