import { Router } from 'express';
import { client, MODEL } from '../claude.js';
import { cleanMessages, lastIsUser } from '../messages.js';

const router = Router();

// POST /api/chat/stream  -> Server-Sent Events: "text" chunks, then "done" (or "error")
router.post('/chat/stream', async (req, res) => {
  const system = String(req.body?.system || '').slice(0, 2000);
  const messages = cleanMessages(req.body?.messages);
  if (!lastIsUser(messages)) {
    return res.status(400).json({ error: { message: 'Send at least one message from the user.' } });
  }

  res.setHeader('Content-Type', 'text/event-stream');
  res.setHeader('Cache-Control', 'no-cache');
  res.setHeader('Connection', 'keep-alive');
  res.setHeader('X-Accel-Buffering', 'no'); // tells nginx not to hold the text back
  res.flushHeaders();

  const send = (event, data) => res.write(`event: ${event}\ndata: ${JSON.stringify(data)}\n\n`);

  const stream = client.messages.stream({
    model: MODEL,
    max_tokens: 600,
    ...(system ? { system } : {}),
    messages,
  });

  // If the user closes the page or presses Stop, stop paying for tokens nobody reads.
  let aborted = false;
  res.on('close', () => {
    if (!res.writableEnded) {
      aborted = true;
      stream.abort();
    }
  });

  stream.on('text', (chunk) => send('text', chunk));

  try {
    const final = await stream.finalMessage();
    send('done', { usage: final.usage, stopReason: final.stop_reason });
  } catch (e) {
    if (!aborted) {
      console.error('[stream]', e?.message);
      send('error', { message: 'The reply was interrupted. Please try again.' });
    }
  } finally {
    res.end();
  }
});

export default router;

import { Component, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';

@Component({
  selector: 'app-stream',
  imports: [FormsModule],
  template: `
    <h1>Streaming reply</h1>
    <p class="hint">Words appear as Claude writes them. Press Stop to cancel; the server stops the request too.</p>

    <div class="card">
      <label for="p">Your prompt</label>
      <textarea id="p" [(ngModel)]="prompt"></textarea>
      <button (click)="start()" [disabled]="running() || !prompt.trim()">Start</button>
      <button class="secondary" (click)="stop()" [disabled]="!running()">Stop</button>
      @if (error()) { <div class="err">{{ error() }}</div> }
      <div class="answer">{{ output() }}@if (running()) { <span class="muted"> ▍</span> }</div>
      @if (info()) { <p class="muted">{{ info() }}</p> }
    </div>
  `,
})
export class StreamPage {
  prompt = 'Write a short professional summary for a welder with 4 years of experience.';
  output = signal('');
  running = signal(false);
  error = signal('');
  info = signal('');
  private controller: AbortController | null = null;

  async start() {
    this.output.set('');
    this.error.set('');
    this.info.set('');
    this.running.set(true);
    this.controller = new AbortController();

    try {
      const response = await fetch('/api/chat/stream', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ messages: [{ role: 'user', content: this.prompt }] }),
        signal: this.controller.signal,
      });
      if (!response.ok || !response.body) throw new Error('bad response');

      // Read the stream piece by piece. Events are separated by a blank line.
      const reader = response.body.getReader();
      const decoder = new TextDecoder();
      let buffer = '';
      while (true) {
        const { value, done } = await reader.read();
        if (done) break;
        buffer += decoder.decode(value, { stream: true });
        const events = buffer.split('\n\n');
        buffer = events.pop() ?? '';
        for (const raw of events) this.handle(raw);
      }
    } catch (e) {
      if ((e as Error).name !== 'AbortError') this.error.set('Could not stream the reply. Please try again.');
    } finally {
      this.running.set(false);
      this.controller = null;
    }
  }

  private handle(raw: string) {
    const event = /^event: (.*)$/m.exec(raw)?.[1];
    const data = /^data: (.*)$/m.exec(raw)?.[1];
    if (!event || data === undefined) return;
    const value = JSON.parse(data);
    if (event === 'text') this.output.update((t) => t + value);
    if (event === 'done') this.info.set(`Done. ${value.usage.output_tokens} output tokens.`);
    if (event === 'error') this.error.set(value.message);
  }

  stop() {
    this.controller?.abort();
    this.info.set('Stopped.');
  }
}

// Retry only the errors that can go away by themselves.
export const isRetryable = (e) =>
  e?.status === 429 || e?.status >= 500 || e?.name === 'APIConnectionError' || e?.name === 'APIConnectionTimeoutError';

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

// Run fn(). If it fails with a retryable error, wait and try again.
// Waits grow each time (exponential backoff) with a little randomness (jitter).
export async function withRetry(fn, { tries = 3, baseMs = 500 } = {}) {
  let attempts = 0;
  for (;;) {
    attempts += 1;
    try {
      return { value: await fn(attempts), attempts };
    } catch (e) {
      if (!isRetryable(e) || attempts >= tries) {
        e.attempts = attempts;
        throw e;
      }
      await sleep(baseMs * 2 ** (attempts - 1) + Math.random() * 200);
    }
  }
}

import { Router } from 'express';
import Anthropic from '@anthropic-ai/sdk';
import { MODEL, textOf } from '../claude.js';
import { withRetry, isRetryable } from '../retry.js';

const router = Router();

// This client does NOT retry by itself and gives up after 20 seconds,
// so you can see our own retry logic working.
const strict = new Anthropic({ maxRetries: 0, timeout: 20_000 });

const fake = (status) => Object.assign(new Error('simulated error'), { status });

// POST /api/reliable-ask  { question, simulate? }   simulate: 'flaky' | 'down' | 'bad'
router.post('/reliable-ask', async (req, res) => {
  const question = String(req.body?.question || '').trim().slice(0, 2000);
  const simulate = String(req.body?.simulate || '');
  if (!question) return res.status(400).json({ error: { message: 'Please type a question.' } });

  try {
    const { value, attempts } = await withRetry(async (attempt) => {
      // Fake failures so you can test without waiting for a real outage.
      if (simulate === 'flaky' && attempt < 3) throw fake(429);
      if (simulate === 'down') throw fake(503);
      if (simulate === 'bad') throw fake(400);

      return strict.messages.create({
        model: MODEL,
        max_tokens: 400,
        messages: [{ role: 'user', content: question }],
      });
    });
    res.json({ text: textOf(value), attempts });
  } catch (e) {
    console.error('[reliable]', e?.status, e?.message);
    const retryable = isRetryable(e);
    res.status(e?.status >= 400 && e?.status < 600 ? e.status : 502).json({
      error: {
        message: retryable ? 'The AI service is busy right now. You can try again.' : 'We could not process that request.',
        retryable,
        attempts: e.attempts ?? 1,
      },
    });
  }
});

export default router;

import { Component, inject, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { HttpClient } from '@angular/common/http';
import { Subscription } from 'rxjs';

@Component({
  selector: 'app-reliable',
  imports: [FormsModule],
  template: `
    <h1>Reliable requests</h1>
