const STOP = new Set('the a an and or of to in for with on at by is are be as we you our your will can from this that it their they them have has not but if'.split(' '));

export const tools = [
  {
    name: 'get_job_keywords',
    description: 'Find the most frequent skills and keywords in a job description. Use this when the user pastes a job post and wants keywords for their resume.',
    input_schema: {
      type: 'object',
      properties: {
        job_text: { type: 'string', description: 'The full job description text' },
        max_keywords: { type: 'integer', description: 'How many keywords to return (default 8)' },
      },
      required: ['job_text'],
    },
  },
  {
    name: 'count_words',
    description: 'Count the words in a piece of text. Use it when the user asks how long a text is.',
    input_schema: {
      type: 'object',
      properties: { text: { type: 'string', description: 'The text to count' } },
      required: ['text'],
    },
  },
];

const handlers = {
  get_job_keywords({ job_text, max_keywords = 8 }) {
    const counts = new Map();
    for (const word of String(job_text).toLowerCase().match(/[a-z][a-z+#.]{2,}/g) || []) {
      if (!STOP.has(word)) counts.set(word, (counts.get(word) || 0) + 1);
    }
    const top = [...counts].sort((a, b) => b[1] - a[1]).slice(0, Math.min(Number(max_keywords) || 8, 20));
    return { keywords: top.map(([word, times]) => ({ word, times })) };
  },
  count_words({ text }) {
    return { words: String(text).trim().split(/\s+/).filter(Boolean).length };
  },
};

export function runTool(name, input) {
  const fn = handlers[name];
  if (!fn) throw new Error(`Unknown tool: ${name}`);
  return fn(input || {});
}

import { Router } from 'express';
import { client, MODEL, textOf } from '../claude.js';
import { tools, runTool } from '../tools.js';

const router = Router();
const MAX_TURNS = 5; // never let the loop run forever

// POST /api/agent  { message }  ->  { text, trace }
router.post('/agent', async (req, res) => {
  const message = String(req.body?.message || '').trim().slice(0, 6000);
  if (!message) return res.status(400).json({ error: { message: 'Please type a message.' } });

  const messages = [{ role: 'user', content: message }];
  const trace = []; // a record of every tool call, shown in the Angular page

  for (let turn = 1; turn <= MAX_TURNS; turn++) {
    const reply = await client.messages.create({ model: MODEL, max_tokens: 800, tools, messages });
    messages.push({ role: 'assistant', content: reply.content });

    // No tool requested: this is the final answer.
    if (reply.stop_reason !== 'tool_use') {
      return res.json({ text: textOf(reply), trace, turns: turn });
    }

    // Run every tool Claude asked for and send back one result for each.
    const results = [];
    for (const block of reply.content) {
      if (block.type !== 'tool_use') continue;
      let output;
      let isError = false;
      try {
        output = runTool(block.name, block.input);
      } catch (e) {
        output = { error: e.message };
        isError = true;
      }
      trace.push({ tool: block.name, input: block.input, output, isError });
      results.push({ type: 'tool_result', tool_use_id: block.id, content: JSON.stringify(output), ...(isError ? { is_error: true } : {}) });
    }
    messages.push({ role: 'user', content: results });
  }

  res.json({ text: 'Stopped: too many steps. Please try a simpler request.', trace, turns: MAX_TURNS });
});

export default router;

