import { z } from 'zod';

// Every tool has: a description for Claude, a JSON Schema Claude must follow,
// a zod schema WE use to check what Claude really sent, and a flag for approval.
// "ctx" is the private data of one chat session (its notes).

export const safeTools = {
  save_note: {
    needsApproval: false,
    description: 'Save a short note for the user, such as a skill to add to the resume.',
    inputSchema: {
      type: 'object',
      properties: {
        title: { type: 'string', description: 'Short title, up to 80 characters' },
        text: { type: 'string', description: 'The note text, up to 1000 characters' },
      },
      required: ['title', 'text'],
    },
    schema: z.object({ title: z.string().min(1).max(80), text: z.string().min(1).max(1000) }),
    run({ title, text }, ctx) {
      const id = String(++ctx.counter);
      ctx.notes.set(id, { id, title, text });
      return { saved: id };
    },
  },
  list_notes: {
    needsApproval: false,
    description: 'List the notes saved so far.',
    inputSchema: { type: 'object', properties: {} },
    schema: z.object({}),
    run(_input, ctx) {
      return { notes: [...ctx.notes.values()] };
    },
  },
  delete_note: {
    needsApproval: true, // hard to undo, so a person must approve it
    description: 'Delete a saved note by its id. The user must approve this action.',
    inputSchema: {
      type: 'object',
      properties: { id: { type: 'string', description: 'The id of the note to delete' } },
      required: ['id'],
    },
    schema: z.object({ id: z.string().min(1).max(20) }),
    run({ id }, ctx) {
      // Ownership check: ctx belongs to this session only, so one user can never reach another user's notes.
      if (!ctx.notes.delete(id)) throw new Error('There is no note with that id.');
      return { deleted: id };
    },
  },
};

export const toolDefs = Object.entries(safeTools).map(([name, t]) => ({
  name,
  description: t.description,
  input_schema: t.inputSchema,
}));

import { Router } from 'express';
import { randomUUID } from 'node:crypto';
import { client, MODEL, textOf } from '../claude.js';
import { safeTools, toolDefs } from '../safe-tools.js';

const router = Router();
const MAX_TURNS = 6;
const SYSTEM = 'You help users improve their resume. You can save, list and delete short notes with the tools. Only delete a note when the user clearly asks.';

// In-memory sessions. A real product would use a database and expire old data.
const sessions = new Map();

function getSession(id) {
  const now = Date.now();
  for (const [key, s] of sessions) if (now - s.touched > 30 * 60 * 1000) sessions.delete(key);
  if (id && sessions.has(id)) {
    const s = sessions.get(id);
    s.touched = now;
    return s;
  }
  const s = { id: randomUUID(), messages: [], notes: new Map(), counter: 0, awaiting: null, touched: now };
  if (sessions.size < 200) sessions.set(s.id, s);
  return s;
}

const errorResult = (id, message) => ({ type: 'tool_result', tool_use_id: id, is_error: true, content: message });

function execute(block, tool, input, session) {
  try {
    const output = tool.run(input, session);
    return { type: 'tool_result', tool_use_id: block.id, content: JSON.stringify(output) };
  } catch (e) {
    return errorResult(block.id, e.message);
  }
}

// Run the conversation until Claude is done OR needs the user to approve something.
async function drive(session) {
  for (let turn = 1; turn <= MAX_TURNS; turn++) {
    const reply = await client.messages.create({
      model: MODEL, max_tokens: 800, system: SYSTEM, tools: toolDefs, messages: session.messages,
    });
    session.messages.push({ role: 'assistant', content: reply.content });
    if (reply.stop_reason !== 'tool_use') return { status: 'done', text: textOf(reply) };

    const results = [];
    const waiting = [];
    for (const block of reply.content.filter((b) => b.type === 'tool_use')) {
      const tool = safeTools[block.name];
      if (!tool) { results.push(errorResult(block.id, 'Unknown tool.')); continue; }

      // Never trust the arguments. Check them with zod and tell Claude what was wrong.
      const parsed = tool.schema.safeParse(block.input);
      if (!parsed.success) {
        const why = parsed.error.issues.map((i) => `${i.path.join('.') || 'input'}: ${i.message}`).join('; ');
        results.push(errorResult(block.id, `Invalid input. ${why}`));
        continue;
      }
      if (tool.needsApproval) { waiting.push({ block, input: parsed.data }); continue; }
      results.push(execute(block, tool, parsed.data, session));
    }

    if (waiting.length) {
      session.awaiting = { results, waiting };
      return { status: 'needs_approval', actions: waiting.map((w) => ({ name: w.block.name, input: w.input })) };
    }
    session.messages.push({ role: 'user', content: results });
  }
  return { status: 'done', text: 'Stopped: too many steps. Please try a simpler request.' };
}

const view = (session, outcome) => ({ sessionId: session.id, notes: [...session.notes.values()], ...outcome });

// POST /api/safe-agent  { sessionId?, message }
router.post('/safe-agent', async (req, res) => {
  const message = String(req.body?.message || '').trim().slice(0, 2000);
  if (!message) return res.status(400).json({ error: { message: 'Please type a message.' } });

  const session = getSession(req.body?.sessionId);
  if (session.awaiting) return res.status(409).json({ error: { message: 'Please approve or deny the pending action first.' } });

  session.messages.push({ role: 'user', content: message });
  res.json(view(session, await drive(session)));
});

// POST /api/safe-agent/decision  { sessionId, approve }
router.post('/safe-agent/decision', async (req, res) => {
  const session = sessions.get(String(req.body?.sessionId || ''));
  if (!session?.awaiting) return res.status(404).json({ error: { message: 'Nothing is waiting for approval.' } });

  const { results, waiting } = session.awaiting;
  session.awaiting = null;
  for (const w of waiting) {
    if (req.body?.approve === true) results.push(execute(w.block, safeTools[w.block.name], w.input, session));
    else results.push(errorResult(w.block.id, 'The user declined this action.'));
  }
  session.messages.push({ role: 'user', content: results });
  res.json(view(session, await drive(session)));
});

export default router;

import { Component, inject, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { HttpClient } from '@angular/common/http';
import { firstValueFrom } from 'rxjs';
import { errorText } from '../util';

type Note = { id: string; title: string; text: string };
type Action = { name: string; input: unknown };
type Reply = { sessionId: string; notes: Note[]; status: 'done' | 'needs_approval'; text?: string; actions?: Action[] };
type Line = { who: 'You' | 'Claude'; text: string };

@Component({
  selector: 'app-safe-agent',
  imports: [FormsModule],
  template: `
    <h1>Safe tools with approval</h1>
    <p class="hint">Saving a note is fine. Deleting one needs your approval. Try: "Save a note called Skills: add MIG welding" and then "Delete note 1".</p>

    <div class="card">
      @for (l of lines(); track $index) { <p><strong>{{ l.who }}:</strong> <span class="answer">{{ l.text }}</span></p> }

      @if (pending(); as actions) {
        <div class="err">
          Claude wants to do this:
          @for (a of actions; track $index) { <pre class="out">{{ a.name }}({{ show(a.input) }})</pre> }
          <button class="danger" (click)="decide(true)" [disabled]="busy()">Approve</button>
          <button class="secondary" (click)="decide(false)" [disabled]="busy()">Deny</button>
        </div>
      }
      @if (error()) { <div class="err">{{ error() }}</div> }

      <label for="m">Message</label>
      <textarea id="m" [(ngModel)]="message" style="min-height:70px" [disabled]="!!pending()"></textarea>
      <button (click)="send()" [disabled]="busy() || !!pending() || !message.trim()">{{ busy() ? 'Working...' : 'Send' }}</button>
    </div>

    <div class="card">
      <h2>Saved notes</h2>
      @for (n of notes(); track n.id) { <p><strong>#{{ n.id }} {{ n.title }}</strong><br />{{ n.text }}</p> } @empty { <p class="muted">No notes.</p> }
    </div>
  `,
})
export class SafeAgentPage {
  private http = inject(HttpClient);
  private sessionId = '';

  message = '';
  busy = signal(false);
  error = signal('');
  lines = signal<Line[]>([]);
  notes = signal<Note[]>([]);
  pending = signal<Action[] | null>(null);

  show(v: unknown) { return JSON.stringify(v); }

  async send() {
    const text = this.message.trim();
    this.lines.update((l) => [...l, { who: 'You', text }]);
    this.message = '';
    await this.call('/api/safe-agent', { sessionId: this.sessionId, message: text });
  }

  async decide(approve: boolean) {
    this.lines.update((l) => [...l, { who: 'You', text: approve ? '(approved)' : '(denied)' }]);
    await this.call('/api/safe-agent/decision', { sessionId: this.sessionId, approve });
  }

  private async call(url: string, body: object) {
    this.busy.set(true);
    this.error.set('');
    try {
      const r = await firstValueFrom(this.http.post<Reply>(url, body));
      this.sessionId = r.sessionId;
      this.notes.set(r.notes);
      if (r.status === 'needs_approval') {
        this.pending.set(r.actions ?? []);
      } else {
        this.pending.set(null);
        this.lines.update((l) => [...l, { who: 'Claude', text: r.text ?? '' }]);
      }
    } catch (e) {
      this.error.set(errorText(e));
    } finally {
      this.busy.set(false);
    }
  }
}

