// A small test set: three short job posts used to compare prompts.
export const labJobs = [
  { id: 'warehouse', text: 'Warehouse associate needed in Leeds. You will pick, pack and label orders, use a hand pallet truck and keep the aisles safe. Early shifts, 6am start. 12.50 per hour. No experience needed, full training given.' },
  { id: 'support', text: 'Customer support executive for a software company in Bengaluru. Answer customer chats and emails, solve billing problems and escalate bugs. Good English required. Experience with a ticket tool such as Zendesk is a plus. Hybrid work, three days in the office.' },
  { id: 'welder', text: 'Experienced MIG welder wanted for a fabrication workshop near Nairobi. Read drawings, weld mild steel frames and check your own work. Valid trade certificate and two years of experience required. Safety boots and gloves provided.' },
];

import { Router } from 'express';
import { client, MODEL, textOf } from '../claude.js';
import { labJobs } from '../lab-jobs.js';
import { rateLimit } from '../rate-limit.js';

const router = Router();

const PROMPT_A = 'Summarise this job post for a candidate:\n\n{{job}}';

const DEFAULT_B = `<instructions>
Summarise the job post for a candidate who reads on a phone.
Write exactly 3 bullet points. Start each line with "- ".
Each bullet is at most 20 words, in plain English.
Mention pay only if the post states it. Never invent details.
</instructions>

<job_post>
{{job}}
</job_post>`;

// The checks are plain code. They are cheap, fast and always give the same answer.
function check(output) {
  const lines = output.split('\n').map((l) => l.trim()).filter(Boolean);
  const bullets = lines.filter((l) => l.startsWith('- '));
  const longest = Math.max(0, ...bullets.map((l) => l.slice(2).split(/\s+/).length));
  return {
    threeBullets: bullets.length === 3 && lines.length === 3,
    shortLines: bullets.length > 0 && longest <= 20,
  };
}

async function run(template, job) {
  const reply = await client.messages.create({
    model: MODEL,
    max_tokens: 400,
    messages: [{ role: 'user', content: template.replace('{{job}}', job) }],
  });
  const text = textOf(reply).trim();
  return { text, checks: check(text), tokens: reply.usage.output_tokens };
}

// GET /api/prompt-lab/default  -> the starting version of prompt B
router.get('/prompt-lab/default', (req, res) => res.json({ promptA: PROMPT_A, promptB: DEFAULT_B }));

// POST /api/prompt-lab  { promptB }  -> runs prompt A and prompt B on every test job
router.post('/prompt-lab', rateLimit({ max: 5, windowMs: 60_000 }), async (req, res) => {
  const promptB = String(req.body?.promptB || DEFAULT_B).slice(0, 3000);
  if (!promptB.includes('{{job}}')) {
    return res.status(400).json({ error: { message: 'Your prompt must contain {{job}} where the job post goes.' } });
  }

  const rows = await Promise.all(
    labJobs.map(async (job) => {
      const [a, b] = await Promise.all([run(PROMPT_A, job.text), run(promptB, job.text)]);
      return { id: job.id, a, b };
    }),
  );
  const passed = (key) => rows.filter((r) => r[key].checks.threeBullets && r[key].checks.shortLines).length;
  res.json({ rows, summary: { total: rows.length, passedA: passed('a'), passedB: passed('b') } });
});

export default router;

import { Component, inject, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { HttpClient } from '@angular/common/http';
import { firstValueFrom } from 'rxjs';
import { errorText } from '../util';

type Result = { text: string; checks: { threeBullets: boolean; shortLines: boolean }; tokens: number };
type Row = { id: string; a: Result; b: Result };
type Run = { rows: Row[]; summary: { total: number; passedA: number; passedB: number } };

@Component({
  selector: 'app-prompt-lab',
  imports: [FormsModule],
  template: `
    <h1>Prompt lab</h1>
    <p class="hint">Compare a plain prompt (A) with your improved prompt (B) on a small test set. Edit B until every check passes.</p>

    <div class="grid2">
      <div class="card"><h2>Prompt A (plain)</h2><pre class="out">{{ promptA }}</pre></div>
      <div class="card"><label for="b">Prompt B (you can edit this)</label><textarea id="b" [(ngModel)]="promptB" style="min-height:230px"></textarea></div>
    </div>
    <button (click)="run()" [disabled]="busy()">{{ busy() ? 'Running 6 requests...' : 'Run the test set' }}</button>
    @if (error()) { <div class="err">{{ error() }}</div> }

    @if (result(); as r) {
      <div class="card">
        <h2>Pass rate: A {{ r.summary.passedA }}/{{ r.summary.total }} &nbsp; B {{ r.summary.passedB }}/{{ r.summary.total }}</h2>
        <table>
          <thead><tr><th>Job</th><th>Prompt A</th><th>Prompt B</th></tr></thead>
          <tbody>
            @for (row of r.rows; track row.id) {
              <tr>
                <td>{{ row.id }}</td>
                <td><div class="answer">{{ row.a.text }}</div>{{ badges(row.a) }}</td>
                <td><div class="answer">{{ row.b.text }}</div>{{ badges(row.b) }}</td>
              </tr>
            }
          </tbody>
        </table>
      </div>
    }
  `,
})
export class PromptLabPage {
  private http = inject(HttpClient);

  promptA = '';
  promptB = '';
  busy = signal(false);
  error = signal('');
  result = signal<Run | null>(null);

  constructor() {
    firstValueFrom(this.http.get<{ promptA: string; promptB: string }>('/api/prompt-lab/default')).then((d) => {
      this.promptA = d.promptA;
      this.promptB = d.promptB;
    });
  }

  badges(r: Result) {
    return `${r.checks.threeBullets ? '✔' : '✘'} exactly 3 bullets   ${r.checks.shortLines ? '✔' : '✘'} 20 words or fewer   (${r.tokens} output tokens)`;
  }

  async run() {
    this.busy.set(true);
    this.error.set('');
    try {
      this.result.set(await firstValueFrom(this.http.post<Run>('/api/prompt-lab', { promptB: this.promptB })));
    } catch (e) {
      this.error.set(errorText(e));
    } finally {
      this.busy.set(false);
    }
  }
}
